/**
 * Configuration Module
 * Centralized configuration management with validation
 */

import { z } from 'zod';
import dotenv from 'dotenv';

// Load environment variables
dotenv.config();

// ============================================================================
// Environment Schema
// ============================================================================

const envSchema = z.object({
  // Application
  NODE_ENV: z.enum(['development', 'production', 'test']).default('development'),
  PORT: z.string().transform(Number).default('3000'),
  LOG_LEVEL: z.enum(['error', 'warn', 'info', 'debug']).default('info'),

  // Database
  DATABASE_URL: z.string().url().optional(),
  DB_HOST: z.string().default('localhost'),
  DB_PORT: z.string().transform(Number).default('5432'),
  DB_NAME: z.string().default('seatsniper'),
  DB_USER: z.string().default('seatsniper'),
  DB_PASSWORD: z.string().optional(),

  // Redis
  REDIS_URL: z.string().optional(),
  REDIS_HOST: z.string().default('localhost'),
  REDIS_PORT: z.string().transform(Number).default('6379'),

  // StubHub API
  STUBHUB_CLIENT_ID: z.string().optional(),
  STUBHUB_CLIENT_SECRET: z.string().optional(),

  // Ticketmaster API
  TICKETMASTER_API_KEY: z.string().optional(),

  // SeatGeek API
  SEATGEEK_CLIENT_ID: z.string().optional(),
  SEATGEEK_CLIENT_SECRET: z.string().optional(),

  // Telegram
  TELEGRAM_BOT_TOKEN: z.string().optional(),

  // Twilio
  TWILIO_ACCOUNT_SID: z.string().optional(),
  TWILIO_AUTH_TOKEN: z.string().optional(),
  TWILIO_PHONE_NUMBER: z.string().optional(),
  TWILIO_WHATSAPP_NUMBER: z.string().optional(),

  // Monitoring
  MONITORED_CITIES: z.string().default('portland,seattle'),
});

// Validate environment
const env = envSchema.parse(process.env);

// ============================================================================
// Configuration Object
// ============================================================================

export const config = {
  // Application settings
  app: {
    env: env.NODE_ENV,
    port: env.PORT,
    logLevel: env.LOG_LEVEL,
    isDevelopment: env.NODE_ENV === 'development',
    isProduction: env.NODE_ENV === 'production',
    isTest: env.NODE_ENV === 'test',
  },

  // Database configuration
  database: {
    url: env.DATABASE_URL || `postgresql://${env.DB_USER}:${env.DB_PASSWORD}@${env.DB_HOST}:${env.DB_PORT}/${env.DB_NAME}`,
    host: env.DB_HOST,
    port: env.DB_PORT,
    name: env.DB_NAME,
    user: env.DB_USER,
    password: env.DB_PASSWORD,
  },

  // Redis configuration
  redis: {
    url: env.REDIS_URL || `redis://${env.REDIS_HOST}:${env.REDIS_PORT}`,
    host: env.REDIS_HOST,
    port: env.REDIS_PORT,
  },

  // StubHub API configuration
  stubhub: {
    clientId: env.STUBHUB_CLIENT_ID || '',
    clientSecret: env.STUBHUB_CLIENT_SECRET || '',
    baseUrl: 'https://api.stubhub.com',
    rateLimit: {
      requestsPerMinute: 10,
    },
    timeout: 10_000,
    retryAttempts: 3,
  },

  // Ticketmaster API configuration
  ticketmaster: {
    apiKey: env.TICKETMASTER_API_KEY || '',
    baseUrl: 'https://app.ticketmaster.com/discovery/v2',
    rateLimit: {
      requestsPerDay: 5000,
    },
    timeout: 10_000,
    retryAttempts: 3,
  },

  // SeatGeek API configuration
  seatgeek: {
    clientId: env.SEATGEEK_CLIENT_ID || '',
    clientSecret: env.SEATGEEK_CLIENT_SECRET || '',
    baseUrl: 'https://api.seatgeek.com/2',
    rateLimit: {
      requestsPerMinute: 60, // SeatGeek is more generous
    },
    timeout: 10_000,
    retryAttempts: 3,
  },

  // Telegram configuration
  telegram: {
    botToken: env.TELEGRAM_BOT_TOKEN || '',
  },

  // Twilio configuration
  twilio: {
    accountSid: env.TWILIO_ACCOUNT_SID || '',
    authToken: env.TWILIO_AUTH_TOKEN || '',
    phoneNumber: env.TWILIO_PHONE_NUMBER || '',
    whatsappNumber: env.TWILIO_WHATSAPP_NUMBER || '',
  },

  // Monitoring configuration
  monitoring: {
    cities: env.MONITORED_CITIES.split(',').map(c => c.trim().toLowerCase()),
    pollingIntervals: {
      highPriority: 2 * 60 * 1000,    // 2 minutes for events <7 days out
      mediumPriority: 10 * 60 * 1000, // 10 minutes for events <30 days out
      lowPriority: 30 * 60 * 1000,    // 30 minutes for events >30 days out
    },
  },

  // City to state mapping for API queries
  cityStateMap: {
    portland: 'OR',
    seattle: 'WA',
    tacoma: 'WA',
    eugene: 'OR',
    spokane: 'WA',
    boise: 'ID',
  } as Record<string, string>,
} as const;

// Export type for use in other modules
export type Config = typeof config;

/**
 * SeatSniper - Ticket Intelligence Platform
 * Main Entry Point
 */

import { config } from './config/index.js';
import { logger } from './utils/logger.js';

// Platform Adapters
import { StubHubAdapter } from './adapters/stubhub/stubhub.adapter.js';
import { TicketmasterAdapter } from './adapters/ticketmaster/ticketmaster.adapter.js';
import { SeatGeekAdapter } from './adapters/seatgeek/seatgeek.adapter.js';
import type { IPlatformAdapter } from './adapters/base/platform-adapter.interface.js';

// Services
import { ValueEngineService } from './services/value-engine/value-engine.service.js';

// Notifications
import { TelegramNotifier } from './notifications/telegram/telegram.notifier.js';
import { SMSNotifier } from './notifications/twilio/sms.notifier.js';
import { WhatsAppNotifier } from './notifications/twilio/whatsapp.notifier.js';
import type { INotifier } from './notifications/base/notifier.interface.js';

// ============================================================================
// Application Class
// ============================================================================

export class SeatSniperApp {
  private adapters: Map<string, IPlatformAdapter> = new Map();
  private notifiers: Map<string, INotifier> = new Map();
  private valueEngine: ValueEngineService;
  private isRunning: boolean = false;

  constructor() {
    this.valueEngine = new ValueEngineService();
  }

  // ==========================================================================
  // Initialization
  // ==========================================================================

  async initialize(): Promise<void> {
    logger.info('🎯 SeatSniper initializing...');

    // Initialize platform adapters
    await this.initializeAdapters();

    // Initialize notification channels
    await this.initializeNotifiers();

    logger.info('✅ SeatSniper initialized successfully');
  }

  private async initializeAdapters(): Promise<void> {
    // StubHub
    if (config.stubhub.clientId && config.stubhub.clientSecret) {
      try {
        const stubhub = new StubHubAdapter();
        await stubhub.initialize();
        this.adapters.set('stubhub', stubhub);
        logger.info('  ✓ StubHub adapter ready');
      } catch (error) {
        logger.warn('  ✗ StubHub adapter failed to initialize', {
          error: error instanceof Error ? error.message : 'Unknown error',
        });
      }
    } else {
      logger.info('  - StubHub adapter skipped (no credentials)');
    }

    // Ticketmaster
    if (config.ticketmaster.apiKey) {
      try {
        const ticketmaster = new TicketmasterAdapter();
        await ticketmaster.initialize();
        this.adapters.set('ticketmaster', ticketmaster);
        logger.info('  ✓ Ticketmaster adapter ready');
      } catch (error) {
        logger.warn('  ✗ Ticketmaster adapter failed to initialize', {
          error: error instanceof Error ? error.message : 'Unknown error',
        });
      }
    } else {
      logger.info('  - Ticketmaster adapter skipped (no credentials)');
    }

    // SeatGeek
    if (config.seatgeek.clientId) {
      try {
        const seatgeek = new SeatGeekAdapter();
        await seatgeek.initialize();
        this.adapters.set('seatgeek', seatgeek);
        logger.info('  ✓ SeatGeek adapter ready');
      } catch (error) {
        logger.warn('  ✗ SeatGeek adapter failed to initialize', {
          error: error instanceof Error ? error.message : 'Unknown error',
        });
      }
    } else {
      logger.info('  - SeatGeek adapter skipped (no credentials)');
    }

    if (this.adapters.size === 0) {
      throw new Error('No platform adapters initialized. Check your API credentials.');
    }
  }

  private async initializeNotifiers(): Promise<void> {
    // Telegram
    if (config.telegram.botToken) {
      try {
        const telegram = new TelegramNotifier();
        await telegram.initialize();
        this.notifiers.set('telegram', telegram);
        logger.info('  ✓ Telegram notifier ready');
      } catch (error) {
        logger.warn('  ✗ Telegram notifier failed to initialize', {
          error: error instanceof Error ? error.message : 'Unknown error',
        });
      }
    } else {
      logger.info('  - Telegram notifier skipped (no bot token)');
    }

    // SMS
    if (config.twilio.accountSid && config.twilio.authToken) {
      try {
        const sms = new SMSNotifier();
        await sms.initialize();
        this.notifiers.set('sms', sms);
        logger.info('  ✓ SMS notifier ready');
      } catch (error) {
        logger.warn('  ✗ SMS notifier failed to initialize', {
          error: error instanceof Error ? error.message : 'Unknown error',
        });
      }
    } else {
      logger.info('  - SMS notifier skipped (no credentials)');
    }

    // WhatsApp
    if (config.twilio.accountSid && config.twilio.authToken && config.twilio.whatsappNumber) {
      try {
        const whatsapp = new WhatsAppNotifier();
        await whatsapp.initialize();
        this.notifiers.set('whatsapp', whatsapp);
        logger.info('  ✓ WhatsApp notifier ready');
      } catch (error) {
        logger.warn('  ✗ WhatsApp notifier failed to initialize', {
          error: error instanceof Error ? error.message : 'Unknown error',
        });
      }
    } else {
      logger.info('  - WhatsApp notifier skipped (no WhatsApp number configured)');
    }

    if (this.notifiers.size === 0) {
      logger.warn('⚠️  No notification channels initialized. Alerts will not be sent.');
    }
  }

  // ==========================================================================
  // Public API
  // ==========================================================================

  /**
   * Get available platform adapters
   */
  getAdapters(): Map<string, IPlatformAdapter> {
    return this.adapters;
  }

  /**
   * Get available notifiers
   */
  getNotifiers(): Map<string, INotifier> {
    return this.notifiers;
  }

  /**
   * Get the Value Engine service
   */
  getValueEngine(): ValueEngineService {
    return this.valueEngine;
  }

  /**
   * Check health of all services
   */
  async healthCheck(): Promise<{
    healthy: boolean;
    adapters: Record<string, { healthy: boolean; latency: number }>;
    notifiers: Record<string, boolean>;
  }> {
    const adapterHealth: Record<string, { healthy: boolean; latency: number }> = {};
    const notifierHealth: Record<string, boolean> = {};

    // Check adapters
    for (const [name, adapter] of this.adapters) {
      const status = await adapter.getHealthStatus();
      adapterHealth[name] = {
        healthy: status.healthy,
        latency: status.latency,
      };
    }

    // Check notifiers (basic connectivity)
    for (const [name, _notifier] of this.notifiers) {
      notifierHealth[name] = true; // Simplified - could add more checks
    }

    const allAdaptersHealthy = Object.values(adapterHealth).every(a => a.healthy);
    const hasNotifiers = Object.keys(notifierHealth).length > 0;

    return {
      healthy: allAdaptersHealthy && hasNotifiers,
      adapters: adapterHealth,
      notifiers: notifierHealth,
    };
  }

  /**
   * Start the monitoring loop (placeholder for full implementation)
   */
  async start(): Promise<void> {
    if (this.isRunning) {
      logger.warn('SeatSniper is already running');
      return;
    }

    this.isRunning = true;
    logger.info('🚀 SeatSniper started');

    // TODO: Implement inventory monitoring loop
    // This would include:
    // 1. Polling events from adapters
    // 2. Scoring listings with ValueEngine
    // 3. Triggering alerts via notifiers
    // 4. Storing data in database
  }

  /**
   * Stop the monitoring loop
   */
  async stop(): Promise<void> {
    if (!this.isRunning) {
      return;
    }

    this.isRunning = false;
    logger.info('🛑 SeatSniper stopped');
  }
}

// ============================================================================
// Main Entry Point
// ============================================================================

async function main(): Promise<void> {
  logger.info('═══════════════════════════════════════════');
  logger.info('  🎯 SEATSNIPER - Ticket Intelligence');
  logger.info('═══════════════════════════════════════════');

  const app = new SeatSniperApp();

  try {
    await app.initialize();

    // Perform health check
    const health = await app.healthCheck();
    logger.info('Health check:', health);

    // For now, just log status
    logger.info('🎫 SeatSniper MVP ready!');
    logger.info(`   Adapters: ${[...app.getAdapters().keys()].join(', ') || 'none'}`);
    logger.info(`   Notifiers: ${[...app.getNotifiers().keys()].join(', ') || 'none'}`);
    logger.info(`   Cities: ${config.monitoring.cities.join(', ')}`);

    // In production, would call app.start() to begin monitoring

  } catch (error) {
    logger.error('Failed to start SeatSniper', {
      error: error instanceof Error ? error.message : 'Unknown error',
    });
    process.exit(1);
  }
}

// Run if this is the main module
main().catch(console.error);

/**
 * Logger Utility
 * Winston-based structured logging with context support
 */

import winston from 'winston';

const { combine, timestamp, printf, colorize, errors } = winston.format;

// Custom format for console output
const consoleFormat = printf(({ level, message, timestamp, service, ...meta }) => {
  const metaStr = Object.keys(meta).length ? ` ${JSON.stringify(meta)}` : '';
  return `${timestamp} [${service || 'seatsniper'}] ${level}: ${message}${metaStr}`;
});

// Create the base logger
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  defaultMeta: { service: 'seatsniper' },
  format: combine(
    errors({ stack: true }),
    timestamp({ format: 'YYYY-MM-DD HH:mm:ss' })
  ),
  transports: [
    // Console transport with colors for development
    new winston.transports.Console({
      format: combine(
        colorize(),
        consoleFormat
      ),
    }),
  ],
});

// Add file transports in production
if (process.env.NODE_ENV === 'production') {
  logger.add(
    new winston.transports.File({
      filename: 'logs/error.log',
      level: 'error',
      format: combine(
        timestamp(),
        winston.format.json()
      ),
    })
  );

  logger.add(
    new winston.transports.File({
      filename: 'logs/combined.log',
      format: combine(
        timestamp(),
        winston.format.json()
      ),
    })
  );
}

/**
 * Create a child logger with additional context
 * @param context Additional context to include in all log messages
 */
export function createLogger(context: Record<string, string>): winston.Logger {
  return logger.child(context);
}

/**
 * Log adapter operations with timing
 */
export function logAdapterOperation(
  adapter: string,
  operation: string,
  startTime: number,
  success: boolean,
  meta?: Record<string, unknown>
): void {
  const duration = Date.now() - startTime;
  const level = success ? 'info' : 'error';

  logger.log(level, `[${adapter}] ${operation}`, {
    adapter,
    operation,
    duration,
    success,
    ...meta,
  });
}

/**
 * Log alert delivery
 */
export function logAlertDelivery(
  channel: string,
  userId: string,
  success: boolean,
  messageId?: string,
  error?: string
): void {
  const level = success ? 'info' : 'error';

  logger.log(level, `Alert delivery via ${channel}`, {
    channel,
    userId,
    success,
    messageId,
    error,
  });
}

export { logger };

/**
 * Rate Limiter Utility
 * Token bucket implementation for API rate limiting
 */

interface RateLimiterConfig {
  /** Number of tokens added per interval */
  tokensPerInterval: number;

  /** Interval type */
  interval: 'second' | 'minute' | 'hour' | 'day';

  /** Maximum tokens that can be stored (burst capacity) */
  maxTokens?: number;
}

const INTERVAL_MS: Record<string, number> = {
  second: 1000,
  minute: 60 * 1000,
  hour: 60 * 60 * 1000,
  day: 24 * 60 * 60 * 1000,
};

export class RateLimiter {
  private tokens: number;
  private maxTokens: number;
  private tokensPerInterval: number;
  private intervalMs: number;
  private lastRefill: number;
  private waitQueue: Array<() => void> = [];

  constructor(config: RateLimiterConfig) {
    this.tokensPerInterval = config.tokensPerInterval;
    this.maxTokens = config.maxTokens ?? config.tokensPerInterval;
    this.intervalMs = INTERVAL_MS[config.interval];
    this.tokens = this.maxTokens;
    this.lastRefill = Date.now();
  }

  /**
   * Refill tokens based on elapsed time
   */
  private refill(): void {
    const now = Date.now();
    const elapsed = now - this.lastRefill;
    const refillAmount = (elapsed / this.intervalMs) * this.tokensPerInterval;

    this.tokens = Math.min(this.maxTokens, this.tokens + refillAmount);
    this.lastRefill = now;
  }

  /**
   * Try to acquire a token immediately
   * @returns true if token was acquired, false otherwise
   */
  tryAcquire(): boolean {
    this.refill();

    if (this.tokens >= 1) {
      this.tokens -= 1;
      return true;
    }

    return false;
  }

  /**
   * Acquire a token, waiting if necessary
   * @returns Promise that resolves when token is acquired
   */
  async acquire(): Promise<void> {
    if (this.tryAcquire()) {
      return;
    }

    // Calculate wait time until next token
    const tokensNeeded = 1 - this.tokens;
    const waitTime = (tokensNeeded / this.tokensPerInterval) * this.intervalMs;

    return new Promise<void>((resolve) => {
      setTimeout(() => {
        this.refill();
        this.tokens -= 1;
        resolve();
        this.processQueue();
      }, waitTime);
    });
  }

  /**
   * Process any waiting requests
   */
  private processQueue(): void {
    while (this.waitQueue.length > 0 && this.tryAcquire()) {
      const next = this.waitQueue.shift();
      next?.();
    }
  }

  /**
   * Get current token count
   */
  getAvailableTokens(): number {
    this.refill();
    return Math.floor(this.tokens);
  }

  /**
   * Get estimated wait time for next token (in ms)
   */
  getWaitTime(): number {
    this.refill();

    if (this.tokens >= 1) {
      return 0;
    }

    const tokensNeeded = 1 - this.tokens;
    return (tokensNeeded / this.tokensPerInterval) * this.intervalMs;
  }
}

/**
 * Create a rate limiter from requests per day
 */
export function createDailyRateLimiter(requestsPerDay: number): RateLimiter {
  // Convert to requests per minute for smoother distribution
  const requestsPerMinute = Math.max(1, Math.floor(requestsPerDay / (24 * 60)));

  return new RateLimiter({
    tokensPerInterval: requestsPerMinute,
    interval: 'minute',
    maxTokens: Math.min(requestsPerMinute * 5, 50), // Allow some burst
  });
}

/**
 * Create a rate limiter from requests per minute
 */
export function createMinuteRateLimiter(requestsPerMinute: number): RateLimiter {
  return new RateLimiter({
    tokensPerInterval: requestsPerMinute,
    interval: 'minute',
    maxTokens: requestsPerMinute,
  });
}

/**
 * Deep Link Generator
 * Generates platform-specific purchase links for ticket listings
 */

import type { Platform } from '../adapters/base/platform-adapter.interface.js';

interface DeepLinkParams {
  platform: Platform;
  eventId: string;
  listingId: string;
  quantity?: number;
}

/**
 * Generate a deep link to the purchase page for a listing
 */
export function generateDeepLink(params: DeepLinkParams): string {
  const { platform, eventId, listingId, quantity } = params;

  switch (platform) {
    case 'stubhub':
      return generateStubHubLink(eventId, listingId, quantity);

    case 'ticketmaster':
      return generateTicketmasterLink(eventId, listingId);

    case 'seatgeek':
      return generateSeatGeekLink(eventId, listingId);

    case 'vividseats':
      return generateVividSeatsLink(eventId, listingId);

    default:
      throw new Error(`Unknown platform: ${platform}`);
  }
}

/**
 * StubHub deep link
 * Format: https://www.stubhub.com/event/{eventId}/?ticket={listingId}&qty={quantity}
 */
function generateStubHubLink(eventId: string, listingId: string, quantity?: number): string {
  const baseUrl = `https://www.stubhub.com/event/${eventId}/`;
  const params = new URLSearchParams({
    ticket: listingId,
  });

  if (quantity) {
    params.set('qty', quantity.toString());
  }

  return `${baseUrl}?${params.toString()}`;
}

/**
 * Ticketmaster deep link
 * Format: https://www.ticketmaster.com/event/{eventId}?listingId={listingId}
 */
function generateTicketmasterLink(eventId: string, listingId: string): string {
  const baseUrl = `https://www.ticketmaster.com/event/${eventId}`;
  const params = new URLSearchParams({
    listingId,
  });

  return `${baseUrl}?${params.toString()}`;
}

/**
 * SeatGeek deep link
 * Format: https://seatgeek.com/checkout/{eventId}/{listingId}
 */
function generateSeatGeekLink(eventId: string, listingId: string): string {
  return `https://seatgeek.com/checkout/${eventId}/${listingId}`;
}

/**
 * Vivid Seats deep link
 * Format: https://www.vividseats.com/checkout?productionId={eventId}&ticketId={listingId}
 */
function generateVividSeatsLink(eventId: string, listingId: string): string {
  const params = new URLSearchParams({
    productionId: eventId,
    ticketId: listingId,
  });

  return `https://www.vividseats.com/checkout?${params.toString()}`;
}

/**
 * Validate that a deep link is properly formatted
 */
export function validateDeepLink(link: string): boolean {
  try {
    const url = new URL(link);
    const validHosts = [
      'www.stubhub.com',
      'stubhub.com',
      'www.ticketmaster.com',
      'ticketmaster.com',
      'seatgeek.com',
      'www.seatgeek.com',
      'www.vividseats.com',
      'vividseats.com',
    ];

    return validHosts.includes(url.hostname);
  } catch {
    return false;
  }
}

/**
 * Extract platform from a deep link URL
 */
export function extractPlatformFromLink(link: string): Platform | null {
  try {
    const url = new URL(link);
    const host = url.hostname.replace('www.', '');

    if (host.includes('stubhub')) return 'stubhub';
    if (host.includes('ticketmaster')) return 'ticketmaster';
    if (host.includes('seatgeek')) return 'seatgeek';
    if (host.includes('vividseats')) return 'vividseats';

    return null;
  } catch {
    return null;
  }
}

/**
 * Platform Adapter Interface
 * Defines the contract for all ticket platform integrations (StubHub, Ticketmaster, etc.)
 */

import type { CircuitBreakerPolicy } from 'cockatiel';

