// ============================================================================
// Listing Types
// ============================================================================

export type Platform = 'stubhub' | 'ticketmaster' | 'seatgeek' | 'vividseats';

export type DeliveryType = 'electronic' | 'instant' | 'physical' | 'willcall';

export interface NormalizedListing {
  platformListingId: string;
  platform: Platform;
  eventId: string;
  section: string;
  row: string;
  seatNumbers?: string[];
  quantity: number;
  pricePerTicket: number;
  totalPrice: number;
  fees: number;
  deliveryType: DeliveryType;
  sellerRating?: number;
  deepLink: string;
  capturedAt: Date;
}

// ============================================================================
// Health Check Types
// ============================================================================

export interface HealthStatus {
  healthy: boolean;
  latency: number;
  lastChecked: Date;
  circuitState?: 'closed' | 'open' | 'half-open';
  errorMessage?: string;
}

// ============================================================================
// Platform Adapter Interface
// ============================================================================

export interface IPlatformAdapter {
  /** Platform configuration */
  readonly config: PlatformConfig;

  /** Circuit breaker policy for resilience */
  readonly circuitBreaker: CircuitBreakerPolicy;

  /**
   * Initialize the adapter (authenticate, validate credentials, etc.)
   * @throws Error if initialization fails
   */
  initialize(): Promise<void>;

  /**
   * Search for events matching the given parameters
   * @param params Search parameters (city, dates, categories)
   * @returns Array of normalized events
   */
  searchEvents(params: EventSearchParams): Promise<NormalizedEvent[]>;

  /**
   * Get all listings for a specific event
   * @param platformEventId The platform-specific event ID
   * @returns Array of normalized listings
   */
  getEventListings(platformEventId: string): Promise<NormalizedListing[]>;

  /**
   * Check the health status of this adapter
   * @returns Health status including latency and circuit state
   */
  getHealthStatus(): Promise<HealthStatus>;
}

/**
 * Circuit Breaker and Resilience Utilities
 * Provides fault tolerance patterns for platform API calls
 */

import {
  CircuitBreakerPolicy,
  ExponentialBackoff,
  retry,
  circuitBreaker,
  bulkhead,
  timeout,
  wrap,
  handleAll,
  ConsecutiveBreaker,
  CircuitState,
} from 'cockatiel';
import { logger } from '../../utils/logger.js';

// ============================================================================
// Types
// ============================================================================

export interface ResilienceConfig {
  /** Platform name for logging */
  platformName: string;

  /** Circuit breaker failure threshold before opening */
  circuitBreakerThreshold?: number;

  /** Time in ms before attempting to close circuit */
  circuitBreakerHalfOpenAfter?: number;

  /** Maximum retry attempts */
  maxRetryAttempts?: number;

  /** Initial retry delay in ms */
  initialRetryDelay?: number;

  /** Maximum retry delay in ms */
  maxRetryDelay?: number;

  /** Request timeout in ms */
  timeoutMs?: number;

  /** Maximum concurrent requests */
  maxConcurrent?: number;

  /** Queue size for bulkhead */
  queueSize?: number;
}

export interface ResiliencePolicies {
  /** Combined policy wrapping all resilience patterns */
  policy: ReturnType<typeof wrap>;

  /** Circuit breaker for monitoring and manual control */
  circuitBreaker: CircuitBreakerPolicy;

  /** Get current circuit state */
  getCircuitState: () => CircuitState;

  /** Check if circuit is allowing requests */
  isHealthy: () => boolean;
}

// ============================================================================
// Default Configuration
// ============================================================================

const DEFAULT_CONFIG: Required<Omit<ResilienceConfig, 'platformName'>> = {
  circuitBreakerThreshold: 5,
  circuitBreakerHalfOpenAfter: 30_000, // 30 seconds
  maxRetryAttempts: 3,
  initialRetryDelay: 1_000, // 1 second
  maxRetryDelay: 10_000, // 10 seconds
  timeoutMs: 10_000, // 10 seconds
  maxConcurrent: 5,
  queueSize: 10,
};

// ============================================================================
// Create Resilience Policies
// ============================================================================

/**
 * Create a set of resilience policies for a platform adapter
 *
 * Policy composition (outer to inner):
 * timeout → retry → circuitBreaker → bulkhead → actual call
 *
 * This means:
 * 1. Overall timeout applies to entire operation including retries
 * 2. Retries happen within the timeout
 * 3. Circuit breaker tracks failures across retries
 * 4. Bulkhead limits concurrent operations
 */
export function createResiliencePolicies(
  config: ResilienceConfig
): ResiliencePolicies {
  const {
    platformName,
    circuitBreakerThreshold = DEFAULT_CONFIG.circuitBreakerThreshold,
    circuitBreakerHalfOpenAfter = DEFAULT_CONFIG.circuitBreakerHalfOpenAfter,
    maxRetryAttempts = DEFAULT_CONFIG.maxRetryAttempts,
    initialRetryDelay = DEFAULT_CONFIG.initialRetryDelay,
    maxRetryDelay = DEFAULT_CONFIG.maxRetryDelay,
    timeoutMs = DEFAULT_CONFIG.timeoutMs,
    maxConcurrent = DEFAULT_CONFIG.maxConcurrent,
    queueSize = DEFAULT_CONFIG.queueSize,
  } = config;

  // -------------------------------------------------------------------------
  // Circuit Breaker
  // Opens after consecutive failures, half-opens after cooldown
  // -------------------------------------------------------------------------
  const breaker = circuitBreaker(handleAll, {
    halfOpenAfter: circuitBreakerHalfOpenAfter,
    breaker: new ConsecutiveBreaker(circuitBreakerThreshold),
  });

  // Log circuit state changes
  breaker.onStateChange((state) => {
    const stateNames: Record<CircuitState, string> = {
      [CircuitState.Closed]: 'CLOSED (healthy)',
      [CircuitState.Open]: 'OPEN (failing)',
      [CircuitState.HalfOpen]: 'HALF-OPEN (testing)',
      [CircuitState.Isolated]: 'ISOLATED (manual)',
    };

    logger.warn(`[${platformName}] Circuit breaker: ${stateNames[state]}`, {
      platform: platformName,
      circuitState: state,
    });
  });

  breaker.onBreak(() => {
    logger.error(`[${platformName}] Circuit breaker OPENED - stopping requests`, {
      platform: platformName,
    });
  });

  breaker.onReset(() => {
    logger.info(`[${platformName}] Circuit breaker CLOSED - resuming requests`, {
      platform: platformName,
    });
  });

  // -------------------------------------------------------------------------
  // Retry with Exponential Backoff + Jitter
  // -------------------------------------------------------------------------
  const retryPolicy = retry(handleAll, {
    maxAttempts: maxRetryAttempts,
    backoff: new ExponentialBackoff({
      initialDelay: initialRetryDelay,
      maxDelay: maxRetryDelay,
      exponent: 2,
    }),
  });

  retryPolicy.onRetry((event) => {
    logger.warn(`[${platformName}] Retrying request (attempt ${event.attempt})`, {
      platform: platformName,
      attempt: event.attempt,
      delay: event.delay,
      error: event.reason?.message,
    });
  });

  retryPolicy.onGiveUp((event) => {
    logger.error(`[${platformName}] Giving up after ${event.attempt} attempts`, {
      platform: platformName,
      attempts: event.attempt,
      error: event.reason?.message,
    });
  });

  // -------------------------------------------------------------------------
  // Bulkhead (Concurrency Limiter)
  // -------------------------------------------------------------------------
  const bulkheadPolicy = bulkhead(maxConcurrent, queueSize);

  bulkheadPolicy.onReject(() => {
    logger.warn(`[${platformName}] Request rejected by bulkhead (queue full)`, {
      platform: platformName,
    });
  });

  // -------------------------------------------------------------------------
  // Timeout
  // -------------------------------------------------------------------------
  const timeoutPolicy = timeout(timeoutMs, 'aggressive');

  timeoutPolicy.onTimeout(() => {
    logger.warn(`[${platformName}] Request timed out after ${timeoutMs}ms`, {
      platform: platformName,
      timeoutMs,
    });
  });

  // -------------------------------------------------------------------------
  // Compose Policies
  // Order: timeout → retry → circuitBreaker → bulkhead
  // -------------------------------------------------------------------------
  const combinedPolicy = wrap(timeoutPolicy, retryPolicy, breaker, bulkheadPolicy);

  return {
    policy: combinedPolicy,
    circuitBreaker: breaker,
    getCircuitState: () => breaker.state,
    isHealthy: () => breaker.state === CircuitState.Closed,
  };
}

// ============================================================================
// Utility Functions
// ============================================================================

/**
 * Check if an error is a circuit breaker rejection
 */
export function isCircuitBreakerOpen(error: unknown): boolean {
  return (
    error instanceof Error &&
    error.name === 'BrokenCircuitError'
  );
}

/**
 * Check if an error is a timeout
 */
export function isTimeoutError(error: unknown): boolean {
  return (
    error instanceof Error &&
    error.name === 'TaskCancelledError'
  );
}

/**
 * Check if an error is a bulkhead rejection
 */
export function isBulkheadRejection(error: unknown): boolean {
  return (
    error instanceof Error &&
    error.name === 'BulkheadRejectedError'
  );
}

/**
 * Categorize an error for better handling
 */
export function categorizeError(error: unknown): {
  category: 'circuit_open' | 'timeout' | 'bulkhead_full' | 'api_error' | 'unknown';
  retryable: boolean;
  message: string;
} {
  if (isCircuitBreakerOpen(error)) {
    return {
      category: 'circuit_open',
      retryable: false,
      message: 'Circuit breaker is open - platform may be unavailable',
    };
  }

  if (isTimeoutError(error)) {
    return {
      category: 'timeout',
      retryable: true,
      message: 'Request timed out',
    };
  }

  if (isBulkheadRejection(error)) {
    return {
      category: 'bulkhead_full',
      retryable: true,
      message: 'Too many concurrent requests - try again later',
    };
  }

  if (error instanceof Error) {
    return {
      category: 'api_error',
      retryable: false,
      message: error.message,
    };
  }

  return {
    category: 'unknown',
    retryable: false,
    message: String(error),
  };
}

/**
 * StubHub Platform Adapter
 * Implements IPlatformAdapter for StubHub Catalog API
 */

import axios, { AxiosInstance, AxiosError } from 'axios';
import type { CircuitBreakerPolicy } from 'cockatiel';
import {
  IPlatformAdapter,
  PlatformConfig,
  EventSearchParams,
  NormalizedEvent,
  NormalizedListing,
  HealthStatus,
} from '../base/platform-adapter.interface.js';
import { createResiliencePolicies, type ResiliencePolicies } from '../base/circuit-breaker.js';
import { createMinuteRateLimiter, RateLimiter } from '../../utils/rate-limiter.js';
import { logger, logAdapterOperation } from '../../utils/logger.js';
import { config } from '../../config/index.js';
import type {
  StubHubTokenResponse,
  StubHubEventResponse,
  StubHubListingResponse,
  StubHubSearchParams,
  StubHubListingParams,
} from './stubhub.types.js';
import { mapEventsToNormalized, mapListingsToNormalized } from './stubhub.mapper.js';

// ============================================================================
// StubHub Adapter Implementation
// ============================================================================

export class StubHubAdapter implements IPlatformAdapter {
  readonly config: PlatformConfig = {
    name: 'stubhub',
    baseUrl: config.stubhub.baseUrl,
    rateLimit: config.stubhub.rateLimit,
    timeout: config.stubhub.timeout,
    retryAttempts: config.stubhub.retryAttempts,
  };

  readonly circuitBreaker: CircuitBreakerPolicy;

  private client: AxiosInstance;
  private rateLimiter: RateLimiter;
  private resilience: ResiliencePolicies;

  // OAuth state
  private accessToken: string | null = null;
  private tokenExpiry: Date | null = null;

  constructor() {
    // Initialize resilience policies
    this.resilience = createResiliencePolicies({
      platformName: 'stubhub',
      circuitBreakerThreshold: 5,
      circuitBreakerHalfOpenAfter: 30_000,
      maxRetryAttempts: 3,
      timeoutMs: this.config.timeout,
    });

    this.circuitBreaker = this.resilience.circuitBreaker;

    // Initialize rate limiter (10 requests per minute)
    this.rateLimiter = createMinuteRateLimiter(
      this.config.rateLimit.requestsPerMinute || 10
    );

    // Initialize HTTP client
    this.client = axios.create({
      baseURL: this.config.baseUrl,
      timeout: this.config.timeout,
      headers: {
        'Accept': 'application/json',
        'Content-Type': 'application/json',
      },
    });
  }

  // ==========================================================================
  // Initialization
  // ==========================================================================

  async initialize(): Promise<void> {
    logger.info('[StubHub] Initializing adapter...');

    if (!config.stubhub.clientId || !config.stubhub.clientSecret) {
      throw new Error('StubHub credentials not configured');
    }

    await this.refreshAccessToken();
    logger.info('[StubHub] Adapter initialized successfully');
  }

  // ==========================================================================
  // OAuth Token Management
  // ==========================================================================

  private async refreshAccessToken(): Promise<void> {
    const startTime = Date.now();

    try {
      const response = await axios.post<StubHubTokenResponse>(
        `${this.config.baseUrl}/sellers/oauth/accesstoken`,
        new URLSearchParams({
          grant_type: 'client_credentials',
          scope: 'read:events',
        }),
        {
          auth: {
            username: config.stubhub.clientId,
            password: config.stubhub.clientSecret,
          },
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded',
          },
          timeout: 10_000,
        }
      );

      this.accessToken = response.data.access_token;
      // Set expiry to 5 minutes before actual expiry for safety margin
      this.tokenExpiry = new Date(
        Date.now() + (response.data.expires_in - 300) * 1000
      );

      // Update default authorization header
      this.client.defaults.headers.common['Authorization'] =
        `Bearer ${this.accessToken}`;

      logAdapterOperation('stubhub', 'token_refresh', startTime, true);
    } catch (error) {
      logAdapterOperation('stubhub', 'token_refresh', startTime, false, {
        error: error instanceof Error ? error.message : 'Unknown error',
      });
      throw new Error(`Failed to refresh StubHub access token: ${error}`);
    }
  }

  private async ensureValidToken(): Promise<void> {
    // Refresh if no token or expiring within 60 seconds
    if (
      !this.accessToken ||
      !this.tokenExpiry ||
      this.tokenExpiry.getTime() - Date.now() < 60_000
    ) {
      await this.refreshAccessToken();
    }
  }

  // ==========================================================================
  // Event Search
  // ==========================================================================

  async searchEvents(params: EventSearchParams): Promise<NormalizedEvent[]> {
    await this.ensureValidToken();
    await this.rateLimiter.acquire();

    const startTime = Date.now();
    const searchParams = this.buildSearchParams(params);

    try {
      const response = await this.resilience.policy.execute(async () => {
        return this.client.get<StubHubEventResponse>('/catalog/events', {
          params: searchParams,
        });
      });

      const events = mapEventsToNormalized(response.data.events || []);

      logAdapterOperation('stubhub', 'search_events', startTime, true, {
        city: params.city,
        resultsFound: events.length,
      });

      return events;
    } catch (error) {
      logAdapterOperation('stubhub', 'search_events', startTime, false, {
        city: params.city,
        error: error instanceof Error ? error.message : 'Unknown error',
      });
      throw this.handleError(error);
    }
  }

  private buildSearchParams(params: EventSearchParams): StubHubSearchParams {
    const state = config.cityStateMap[params.city.toLowerCase()];

    return {
      city: params.city,
      state,
      country: 'US',
      minDate: params.startDate.toISOString().split('T')[0],
      maxDate: params.endDate.toISOString().split('T')[0],
      q: params.keyword,
      rows: params.limit || 100,
      sort: 'eventDateLocal asc',
    };
  }

  // ==========================================================================
  // Event Listings
  // ==========================================================================

  async getEventListings(platformEventId: string): Promise<NormalizedListing[]> {
    await this.ensureValidToken();
    await this.rateLimiter.acquire();

    const startTime = Date.now();
    const listingParams: StubHubListingParams = {
      rows: 250,
      sort: 'price asc',
    };

    try {
      const response = await this.resilience.policy.execute(async () => {
        return this.client.get<StubHubListingResponse>(
          `/catalog/events/${platformEventId}/listings`,
          { params: listingParams }
        );
      });

      const listings = mapListingsToNormalized(
        response.data.listings || [],
        platformEventId
      );

      logAdapterOperation('stubhub', 'get_listings', startTime, true, {
        eventId: platformEventId,
        listingsFound: listings.length,
      });

      return listings;
    } catch (error) {
      logAdapterOperation('stubhub', 'get_listings', startTime, false, {
        eventId: platformEventId,
        error: error instanceof Error ? error.message : 'Unknown error',
      });
      throw this.handleError(error);
    }
  }

  // ==========================================================================
  // Health Check
  // ==========================================================================

  async getHealthStatus(): Promise<HealthStatus> {
    const startTime = Date.now();

    try {
      await this.ensureValidToken();

      // Simple health check - search for any event
      await this.client.get('/catalog/events', {
        params: { rows: 1 },
        timeout: 5_000,
      });

      return {
        healthy: true,
        latency: Date.now() - startTime,
        lastChecked: new Date(),
        circuitState: this.getCircuitState(),
      };
    } catch (error) {
      return {
        healthy: false,
        latency: Date.now() - startTime,
        lastChecked: new Date(),
        circuitState: this.getCircuitState(),
        errorMessage: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }

  private getCircuitState(): HealthStatus['circuitState'] {
    const state = this.resilience.getCircuitState();
    // Map cockatiel CircuitState to our simplified state
    if (state === 0) return 'closed';
    if (state === 1) return 'open';
    return 'half-open';
  }

  // ==========================================================================
  // Error Handling
  // ==========================================================================

  private handleError(error: unknown): Error {
    if (axios.isAxiosError(error)) {
      const axiosError = error as AxiosError;

      if (axiosError.response) {
        const status = axiosError.response.status;

        if (status === 401) {
          // Clear token to force refresh on next request
          this.accessToken = null;
          this.tokenExpiry = null;
          return new Error('StubHub authentication failed - token cleared');
        }

        if (status === 429) {
          return new Error('StubHub rate limit exceeded');
        }

        if (status >= 500) {
          return new Error(`StubHub server error: ${status}`);
        }

        return new Error(
          `StubHub API error: ${status} - ${axiosError.response.statusText}`
        );
      }

      if (axiosError.code === 'ECONNABORTED') {
        return new Error('StubHub request timed out');
      }

      return new Error(`StubHub network error: ${axiosError.message}`);
    }

    if (error instanceof Error) {
      return error;
    }

    return new Error(`StubHub unknown error: ${String(error)}`);
  }
}

