/**
 * Ticketmaster Data Mapper
 * Transforms Ticketmaster API responses to normalized types
 */

import type {
  NormalizedEvent,
  NormalizedListing,
  EventCategory,
  DeliveryType,
} from '../base/platform-adapter.interface.js';
import type {
  TicketmasterEvent,
  TicketmasterOffer,
  TicketmasterClassification,
} from './ticketmaster.types.js';
import { generateDeepLink } from '../../utils/deep-link-generator.js';

// ============================================================================
// Event Mapping
// ============================================================================

/**
 * Map Ticketmaster event to normalized event format
 */
export function mapToNormalizedEvent(event: TicketmasterEvent): NormalizedEvent {
  const venue = event._embedded?.venues?.[0];

  // Parse datetime - prefer dateTime, fallback to localDate + localTime
  let eventDateTime: Date;
  if (event.dates.start.dateTime) {
    eventDateTime = new Date(event.dates.start.dateTime);
  } else {
    const dateStr = event.dates.start.localDate;
    const timeStr = event.dates.start.localTime || '19:00:00';
    eventDateTime = new Date(`${dateStr}T${timeStr}`);
  }

  return {
    platformId: event.id,
    platform: 'ticketmaster',
    name: event.name,
    venue: {
      id: venue?.id || 'unknown',
      name: venue?.name || 'Unknown Venue',
      city: venue?.city?.name || 'Unknown',
      state: venue?.state?.stateCode || 'XX',
    },
    dateTime: eventDateTime,
    category: mapCategory(event.classifications),
    url: event.url,
    imageUrl: selectBestImage(event.images),
    seatMapUrl: event.seatmap?.staticUrl,
  };
}

/**
 * Map Ticketmaster classification to normalized category
 */
function mapCategory(
  classifications?: TicketmasterClassification[]
): EventCategory {
  if (!classifications?.length) {
    return EventCategory.CONCERTS; // Default
  }

  const primary = classifications.find(c => c.primary) || classifications[0];
  const segmentName = primary.segment?.name?.toLowerCase() || '';
  const genreName = primary.genre?.name?.toLowerCase() || '';

  if (segmentName === 'music' || genreName.includes('rock') ||
      genreName.includes('pop') || genreName.includes('hip-hop')) {
    return EventCategory.CONCERTS;
  }
  if (segmentName === 'sports') {
    return EventCategory.SPORTS;
  }
  if (segmentName === 'arts & theatre' || genreName.includes('theatre') ||
      genreName.includes('broadway') || genreName.includes('musical')) {
    return EventCategory.THEATER;
  }
  if (genreName.includes('comedy')) {
    return EventCategory.COMEDY;
  }
  if (genreName.includes('festival') || segmentName.includes('festival')) {
    return EventCategory.FESTIVALS;
  }

  return EventCategory.CONCERTS; // Default fallback
}

/**
 * Select the best quality image from available images
 */
function selectBestImage(images?: TicketmasterEvent['images']): string | undefined {
  if (!images?.length) return undefined;

  // Prefer 16_9 ratio, then largest by width
  const preferred = images.find(
    img => img.ratio === '16_9' && (img.width || 0) >= 640
  );

  if (preferred) return preferred.url;

  // Sort by width descending and return largest
  const sorted = [...images].sort((a, b) => (b.width || 0) - (a.width || 0));
  return sorted[0]?.url;
}

// ============================================================================
// Listing/Offer Mapping
// ============================================================================

/**
 * Map Ticketmaster offer to normalized listing format
 * Note: Ticketmaster offers structure varies between primary and resale
 */
export function mapToNormalizedListing(
  offer: TicketmasterOffer,
  eventId: string
): NormalizedListing {
  // Parse section/row from offer
  const section = offer.section || offer.area?.name || 'Unknown';
  const row = offer.row || '';
  const seatNumbers = offer.seats;

  // Calculate prices
  const totalPrice = offer.prices?.find(p => p.type === 'total');
  const facePrice = offer.prices?.find(p => p.type === 'face');
  const feePrice = offer.prices?.find(p => p.type === 'fee');

  const quantity = offer.quantity?.total || 1;
  const pricePerTicket = totalPrice
    ? totalPrice.value / quantity
    : facePrice?.value || 0;

  return {
    platformListingId: offer.id,
    platform: 'ticketmaster',
    eventId,
    section,
    row,
    seatNumbers,
    quantity,
    pricePerTicket,
    totalPrice: totalPrice?.value || pricePerTicket * quantity,
    fees: feePrice?.value || 0,
    deliveryType: mapDeliveryType(offer.deliveryMethods),
    sellerRating: undefined, // Ticketmaster doesn't provide seller ratings
    deepLink: generateDeepLink({
      platform: 'ticketmaster',
      eventId,
      listingId: offer.id,
    }),
    capturedAt: new Date(),
  };
}

/**
 * Map Ticketmaster delivery methods to normalized delivery type
 */
function mapDeliveryType(
  methods?: Array<{ type: string; name: string }>
): DeliveryType {
  if (!methods?.length) return 'electronic';

  const types = methods.map(m => m.type.toLowerCase());

  if (types.some(t => t.includes('instant') || t.includes('mobile'))) {
    return 'instant';
  }
  if (types.some(t => t.includes('electronic') || t.includes('digital'))) {
    return 'electronic';
  }
  if (types.some(t => t.includes('willcall') || t.includes('will call'))) {
    return 'willcall';
  }
  if (types.some(t => t.includes('mail') || t.includes('ship'))) {
    return 'physical';
  }

  return 'electronic'; // Default
}

// ============================================================================
// Batch Mapping
// ============================================================================

/**
 * Map array of Ticketmaster events to normalized events
 */
export function mapEventsToNormalized(
  events: TicketmasterEvent[]
): NormalizedEvent[] {
  return events.map(mapToNormalizedEvent);
}

/**
 * Map array of Ticketmaster offers to normalized listings
 * Filters to resale offers only (primary sales are not what we track)
 */
export function mapOffersToNormalized(
  offers: TicketmasterOffer[],
  eventId: string
): NormalizedListing[] {
  return offers
    .filter(offer => offer.type === 'resale')
    .map(offer => mapToNormalizedListing(offer, eventId));
}

/**
 * SeatGeek Platform Adapter
 * Integrates with SeatGeek API for event discovery and listings
 */

import axios from 'axios';
import type { AxiosInstance } from 'axios';
import type { CircuitBreakerPolicy } from 'cockatiel';
import type {
  IPlatformAdapter,
  PlatformConfig,
  EventSearchParams,
  NormalizedEvent,
  NormalizedListing,
  HealthStatus,
} from '../base/platform-adapter.interface.js';
import { createResiliencePolicies, type ResiliencePolicies } from '../base/circuit-breaker.js';
import type {
  SeatGeekResponse,
  SeatGeekEvent,
  SeatGeekListingsResponse,
  SeatGeekSearchParams,
} from './seatgeek.types.js';
import { isSeatGeekError } from './seatgeek.types.js';
import { mapEventsToNormalized, mapListingsToNormalized } from './seatgeek.mapper.js';
import { logger } from '../../utils/logger.js';
import { config } from '../../config/index.js';

// ============================================================================
// SeatGeek Adapter Implementation
// ============================================================================

export class SeatGeekAdapter implements IPlatformAdapter {
  readonly config: PlatformConfig = {
    name: 'SeatGeek',
    baseUrl: config.seatgeek.baseUrl,
    rateLimit: {
      requestsPerMinute: config.seatgeek.rateLimit.requestsPerMinute,
    },
    timeout: config.seatgeek.timeout,
    retryAttempts: config.seatgeek.retryAttempts,
  };

  readonly circuitBreaker: CircuitBreakerPolicy;

  private resilience: ResiliencePolicies;
  private client: AxiosInstance;
  private isInitialized: boolean = false;

  constructor() {
    this.resilience = createResiliencePolicies({
      platformName: 'SeatGeek',
      circuitBreakerThreshold: 5,
      circuitBreakerHalfOpenAfter: 30_000,
      maxRetryAttempts: config.seatgeek.retryAttempts,
      timeoutMs: config.seatgeek.timeout,
    });
    this.circuitBreaker = this.resilience.circuitBreaker;

    this.client = axios.create({
      baseURL: this.config.baseUrl,
      timeout: this.config.timeout,
      headers: {
        Accept: 'application/json',
      },
    });
  }

  // ==========================================================================
  // Initialization
  // ==========================================================================

  async initialize(): Promise<void> {
    if (this.isInitialized) return;

    if (!config.seatgeek.clientId) {
      throw new Error('SeatGeek client ID not configured');
    }

    try {
      // Test API connectivity with a simple venues query
      const response = await this.client.get('/venues', {
        params: {
          client_id: config.seatgeek.clientId,
          client_secret: config.seatgeek.clientSecret,
          city: 'Portland',
          state: 'OR',
          per_page: 1,
        },
      });

      if (isSeatGeekError(response.data)) {
        throw new Error(response.data.message);
      }

      logger.info('[SeatGeek] API connection verified');
      this.isInitialized = true;
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      throw new Error(`Failed to initialize SeatGeek adapter: ${message}`);
    }
  }

  // ==========================================================================
  // Event Search
  // ==========================================================================

  async searchEvents(params: EventSearchParams): Promise<NormalizedEvent[]> {
    return this.resilience.policy.execute(async () => {
      const searchParams = this.buildSearchParams(params);

      const response = await this.client.get<SeatGeekResponse<SeatGeekEvent>>(
        '/events',
        { params: searchParams }
      );

      if (isSeatGeekError(response.data)) {
        throw new Error(response.data.message);
      }

      const events = response.data.events || [];

      logger.debug(`[SeatGeek] Found ${events.length} events`, {
        city: params.city,
        total: response.data.meta?.total || 0,
      });

      return mapEventsToNormalized(events);
    });
  }

  /**
   * Build SeatGeek search parameters from normalized params
   */
  private buildSearchParams(params: EventSearchParams): SeatGeekSearchParams {
    const searchParams: SeatGeekSearchParams = {
      client_id: config.seatgeek.clientId,
      client_secret: config.seatgeek.clientSecret || undefined,
      'venue.city': params.city,
      'datetime_local.gte': params.startDate.toISOString().split('T')[0],
      'datetime_local.lte': params.endDate.toISOString().split('T')[0],
      per_page: params.limit || 50,
      sort: 'datetime_local',
    };

    // Map categories to SeatGeek taxonomies
    if (params.categories?.length) {
      const taxonomyMap: Record<string, string> = {
        concerts: 'concert',
        sports: 'sports',
        theater: 'theater',
        comedy: 'comedy',
        festivals: 'concert',
      };

      const firstCategory = params.categories[0];
      const taxonomy = taxonomyMap[firstCategory];
      if (taxonomy) {
        searchParams['taxonomies.name'] = taxonomy;
      }
    }

    if (params.keyword) {
      searchParams.q = params.keyword;
    }

    return searchParams;
  }

  // ==========================================================================
  // Event Listings
  // ==========================================================================

  async getEventListings(platformEventId: string): Promise<NormalizedListing[]> {
    return this.resilience.policy.execute(async () => {
      // SeatGeek listings endpoint
      const response = await this.client.get<SeatGeekListingsResponse>(
        `/events/${platformEventId}/listings`,
        {
          params: {
            client_id: config.seatgeek.clientId,
            client_secret: config.seatgeek.clientSecret || undefined,
          },
        }
      );

      if (isSeatGeekError(response.data)) {
        throw new Error(response.data.message);
      }

      const listings = response.data.listings || [];

      logger.debug(`[SeatGeek] Found ${listings.length} listings for event ${platformEventId}`);

      return mapListingsToNormalized(listings, platformEventId);
    });
  }

  // ==========================================================================
  // Venue Seat Map URL
  // ==========================================================================

  /**
   * Get seat map URL for a venue
   * SeatGeek provides seating chart URLs in venue data
   */
  async getVenueSeatMapUrl(venueId: string): Promise<string | undefined> {
    try {
      const response = await this.client.get(`/venues/${venueId}`, {
        params: {
          client_id: config.seatgeek.clientId,
          client_secret: config.seatgeek.clientSecret || undefined,
        },
      });

      if (isSeatGeekError(response.data)) {
        return undefined;
      }

      const venue = response.data;
      return venue.seating_chart_url_large || venue.seating_chart_url;
    } catch {
      return undefined;
    }
  }

  /**
   * Search for a venue by name and city
   */
  async findVenue(name: string, city: string): Promise<{
    id: string;
    seatMapUrl?: string;
  } | undefined> {
    try {
      const response = await this.client.get('/venues', {
        params: {
          client_id: config.seatgeek.clientId,
          client_secret: config.seatgeek.clientSecret || undefined,
          q: name,
          city,
          per_page: 5,
        },
      });

      if (isSeatGeekError(response.data)) {
        return undefined;
      }

      const venues = response.data.venues || [];
      if (venues.length === 0) return undefined;

      // Find best match
      const normalizedName = name.toLowerCase();
      const match = venues.find((v: { name: string }) =>
        v.name.toLowerCase().includes(normalizedName) ||
        normalizedName.includes(v.name.toLowerCase())
      ) || venues[0];

      return {
        id: match.id.toString(),
        seatMapUrl: match.seating_chart_url_large || match.seating_chart_url,
      };
    } catch {
      return undefined;
    }
  }

  // ==========================================================================
  // Health Check
  // ==========================================================================

  async getHealthStatus(): Promise<HealthStatus> {
    const startTime = Date.now();

    try {
      const response = await this.client.get('/venues', {
        params: {
          client_id: config.seatgeek.clientId,
          per_page: 1,
        },
        timeout: 5000,
      });

      const latency = Date.now() - startTime;

      if (isSeatGeekError(response.data)) {
        return {
          healthy: false,
          latency,
          lastChecked: new Date(),
          errorMessage: response.data.message,
        };
      }

      return {
        healthy: true,
        latency,
        lastChecked: new Date(),
        circuitState: 'closed',
      };
    } catch (error) {
      return {
        healthy: false,
        latency: Date.now() - startTime,
        lastChecked: new Date(),
        errorMessage: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }
}

