/**
 * Telegram Notifier
 * Sends alerts via Telegram Bot API with seat map visualization
 */

import { Telegraf } from 'telegraf';
import type {
  INotifier,
  AlertPayload,
  NotificationResult,
  NotificationChannel,
  DeliveryStatus,
} from '../base/notifier.interface.js';
import { TelegramFormatter } from './telegram.formatter.js';
import { SeatMapService } from '../../venues/seat-map.service.js';
import { logger, logAlertDelivery } from '../../utils/logger.js';
import { config } from '../../config/index.js';

// ============================================================================
// Telegram Notifier Implementation
// ============================================================================

export class TelegramNotifier implements INotifier {
  readonly channel: NotificationChannel = 'telegram';

  private bot: Telegraf;
  private formatter: TelegramFormatter;
  private seatMapService: SeatMapService;
  private isInitialized: boolean = false;

  constructor() {
    this.bot = new Telegraf(config.telegram.botToken);
    this.formatter = new TelegramFormatter();
    this.seatMapService = new SeatMapService();
  }

  // ==========================================================================
  // Initialization
  // ==========================================================================

  async initialize(): Promise<void> {
    if (this.isInitialized) return;

    if (!config.telegram.botToken) {
      throw new Error('Telegram bot token not configured');
    }

    try {
      // Verify bot token by getting bot info
      const botInfo = await this.bot.telegram.getMe();
      logger.info(`[Telegram] Bot initialized: @${botInfo.username}`, {
        botId: botInfo.id,
        username: botInfo.username,
      });

      this.isInitialized = true;
    } catch (error) {
      throw new Error(`Failed to initialize Telegram bot: ${error}`);
    }
  }

  // ==========================================================================
  // Send Alert
  // ==========================================================================

  async sendAlert(payload: AlertPayload): Promise<NotificationResult> {
    const startTime = Date.now();

    try {
      await this.ensureInitialized();

      // Try to send seat map image first (if available)
      await this.sendSeatMapImage(payload);

      const message = this.formatter.formatAlert(payload);

      const result = await this.bot.telegram.sendMessage(
        payload.userId,
        message,
        {
          parse_mode: 'MarkdownV2',
          disable_web_page_preview: false,
        }
      );

      const latency = Date.now() - startTime;

      logAlertDelivery(
        'telegram',
        payload.userId,
        true,
        result.message_id.toString()
      );

      logger.info(`[Telegram] Alert sent successfully`, {
        chatId: payload.userId,
        messageId: result.message_id,
        latency,
        listingsCount: payload.listings.length,
      });

      return {
        success: true,
        channel: 'telegram',
        messageId: result.message_id.toString(),
        timestamp: new Date(),
        deliveryStatus: 'delivered',
      };
    } catch (error) {
      const latency = Date.now() - startTime;
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';

      logAlertDelivery('telegram', payload.userId, false, undefined, errorMessage);

      logger.error(`[Telegram] Failed to send alert`, {
        chatId: payload.userId,
        error: errorMessage,
        latency,
      });

      // Handle specific Telegram errors
      const handled = this.handleTelegramError(error, payload.userId);

      return {
        success: false,
        channel: 'telegram',
        error: handled.message,
        timestamp: new Date(),
        deliveryStatus: 'failed',
      };
    }
  }

  // ==========================================================================
  // Seat Map Image Support
  // ==========================================================================

  /**
   * Send a seat map image before the text alert
   * Tries: 1) Platform API URL (Ticketmaster/SeatGeek), 2) Local highlighted map, 3) Skip
   */
  private async sendSeatMapImage(payload: AlertPayload): Promise<void> {
    try {
      // Check if we can get a seat map (from URL or local)
      if (!this.seatMapService.canGetSeatMap(payload.seatMapUrl, payload.venueName)) {
        logger.debug(`[Telegram] No seat map available for ${payload.venueName}`);
        return;
      }

      let imageBuffer: Buffer | null = null;
      let mapSource: 'api' | 'local' = 'api';

      // Strategy 1: Try to fetch from platform API URL (Ticketmaster/SeatGeek)
      if (payload.seatMapUrl) {
        imageBuffer = await this.seatMapService.fetchSeatMapFromUrl(payload.seatMapUrl);
        if (imageBuffer) {
          mapSource = 'api';
        }
      }

      // Strategy 2: Fall back to local highlighted map (if we have section coordinates)
      if (!imageBuffer && this.seatMapService.hasVenue(payload.venueName)) {
        const sections = payload.listings.slice(0, 5).map((listing, idx) => ({
          sectionName: listing.section,
          rank: idx + 1,
        }));

        imageBuffer = await this.seatMapService.generateMultiHighlightMap(
          payload.venueName,
          sections
        );
        mapSource = 'local';
      }

      if (!imageBuffer) {
        logger.debug(`[Telegram] Failed to get seat map for ${payload.venueName}`);
        return;
      }

      // Build caption with venue info
      const officialMapUrl = this.seatMapService.getOfficialMapUrl(payload.venueName);
      let caption = `🗺️ *${this.formatter.escapeMarkdown(payload.venueName)} Seat Map*\n`;

      if (mapSource === 'local') {
        caption += `_Highlighted sections show your top deals_\n\n`;
        caption += `🥇 Gold \\= \\#1 Deal  🥈 Silver \\= \\#2  🥉 Bronze \\= \\#3`;
      } else {
        caption += `_Review seating layout before purchase_`;
      }

      if (officialMapUrl) {
        caption += `\n\n[📍 View Interactive Map](${officialMapUrl})`;
      }

      // Send the image
      await this.bot.telegram.sendPhoto(
        payload.userId,
        { source: imageBuffer },
        {
          caption,
          parse_mode: 'MarkdownV2',
        }
      );

      logger.info(`[Telegram] Seat map sent for ${payload.venueName}`, {
        chatId: payload.userId,
        source: mapSource,
      });
    } catch (error) {
      // Non-fatal - log and continue with text alert
      logger.warn(`[Telegram] Failed to send seat map image`, {
        venue: payload.venueName,
        error: error instanceof Error ? error.message : 'Unknown error',
      });
    }
  }

  // ==========================================================================
  // Recipient Validation
  // ==========================================================================

  async validateRecipient(chatId: string): Promise<boolean> {
    try {
      await this.ensureInitialized();

      // Try to get chat info - will fail if bot can't access the chat
      await this.bot.telegram.getChat(chatId);
      return true;
    } catch (error) {
      logger.warn(`[Telegram] Invalid recipient: ${chatId}`, {
        error: error instanceof Error ? error.message : 'Unknown error',
      });
      return false;
    }
  }

  // ==========================================================================
  // Delivery Status
  // ==========================================================================

  async getDeliveryStatus(_messageId: string): Promise<DeliveryStatus> {
    // Telegram doesn't provide delivery receipts for bots
    // If sendMessage succeeded, we assume it was delivered
    return 'delivered';
  }

  // ==========================================================================
  // Private Helpers
  // ==========================================================================

  private async ensureInitialized(): Promise<void> {
    if (!this.isInitialized) {
      await this.initialize();
    }
  }

  /**
   * Handle Telegram-specific errors
   */
  private handleTelegramError(
    error: unknown,
    chatId: string
  ): { message: string; shouldDeactivate: boolean } {
    if (!(error instanceof Error)) {
      return { message: 'Unknown error', shouldDeactivate: false };
    }

    const message = error.message.toLowerCase();

    // User blocked the bot
    if (message.includes('forbidden') || message.includes('blocked')) {
      logger.warn(`[Telegram] User blocked bot: ${chatId}`);
      return {
        message: 'User has blocked the bot',
        shouldDeactivate: true,
      };
    }

    // Chat not found (user deleted account or never started chat)
    if (message.includes('chat not found')) {
      logger.warn(`[Telegram] Chat not found: ${chatId}`);
      return {
        message: 'Chat not found - user may have deleted account',
        shouldDeactivate: true,
      };
    }

    // Rate limited
    if (message.includes('too many requests') || message.includes('429')) {
      logger.warn(`[Telegram] Rate limited`);
      return {
        message: 'Rate limited - will retry later',
        shouldDeactivate: false,
      };
    }

    // Bad request (malformed message)
    if (message.includes('bad request') || message.includes('400')) {
      logger.error(`[Telegram] Bad request - message may be malformed`);
      return {
        message: 'Invalid message format',
        shouldDeactivate: false,
      };
    }

    return { message: error.message, shouldDeactivate: false };
  }

  /**
   * Send a simple text message (for testing)
   */
  async sendTestMessage(chatId: string, text: string): Promise<boolean> {
    try {
      await this.ensureInitialized();
      await this.bot.telegram.sendMessage(chatId, text);
      return true;
    } catch {
      return false;
    }
  }
}

/**
 * Telegram Message Formatter
 * Formats alerts for Telegram using MarkdownV2
 */

import type { AlertPayload, TopValueListing } from '../base/notifier.interface.js';

// ============================================================================
// Telegram Formatter
// ============================================================================

export class TelegramFormatter {
  /**
   * Format a full alert message for Telegram
   */
  formatAlert(payload: AlertPayload): string {
    const header = this.formatHeader(payload);
    const listings = payload.listings.map(l => this.formatListing(l)).join('\n\n');
    const footer = this.formatFooter();

    return `${header}\n\n${listings}${footer}`;
  }

  /**
   * Format the alert header
   */
  private formatHeader(payload: AlertPayload): string {
    const eventDate = this.formatDate(payload.eventDate);
    const alertIcon = this.getAlertIcon(payload.alertType);

    return this.escapeMarkdown(
      `${alertIcon} SEATSNIPER ALERT\n` +
      `━━━━━━━━━━━━━━━━━━━━━\n` +
      `🎫 ${payload.eventName}\n` +
      `📍 ${payload.venueName}, ${payload.venueCity}\n` +
      `📅 ${eventDate}\n` +
      `━━━━━━━━━━━━━━━━━━━━━\n` +
      `🔥 TOP ${payload.listings.length} VALUE PICKS:`
    );
  }

  /**
   * Format a single listing
   */
  private formatListing(listing: TopValueListing): string {
    const platformBadge = this.getPlatformBadge(listing.platform);
    const scoreEmoji = this.getScoreEmoji(listing.valueScore);

    const details = this.escapeMarkdown(
      `${listing.rank}\\. ${platformBadge} Section ${listing.section}, Row ${listing.row}\n` +
      `   💰 $${listing.pricePerTicket}/ticket \\(${listing.quantity} avail\\)\n` +
      `   ${scoreEmoji} Value Score: ${listing.valueScore}/100\n` +
      `   📊 ${listing.recommendation}`
    );

    // Deep link is not escaped - Telegram handles URLs specially
    const buyLink = `   [🛒 Buy Now](${listing.deepLink})`;

    return details + '\n' + buyLink;
  }

  /**
   * Format the footer
   */
  private formatFooter(): string {
    return '\n\n' + this.escapeMarkdown(
      '━━━━━━━━━━━━━━━━━━━━━\n' +
      '⚠️ Prices subject to change\\. Click links to purchase\\.'
    );
  }

  /**
   * Format date for display
   */
  private formatDate(date: Date): string {
    return date.toLocaleDateString('en-US', {
      weekday: 'short',
      month: 'short',
      day: 'numeric',
      hour: 'numeric',
      minute: '2-digit',
    });
  }

  /**
   * Get alert icon based on type
   */
  private getAlertIcon(alertType: string): string {
    const icons: Record<string, string> = {
      new_listing: '🆕',
      price_drop: '📉',
      high_value: '🎯',
      daily_digest: '📋',
    };
    return icons[alertType] || '🎫';
  }

  /**
   * Get platform badge emoji
   */
  private getPlatformBadge(platform: string): string {
    const badges: Record<string, string> = {
      stubhub: '🟢',      // Green for StubHub
      ticketmaster: '🔵', // Blue for Ticketmaster
      seatgeek: '🟠',     // Orange for SeatGeek
      vividseats: '🟣',   // Purple for Vivid Seats
    };
    return badges[platform] || '⚪';
  }

  /**
   * Get score emoji based on value
   */
  private getScoreEmoji(score: number): string {
    if (score >= 85) return '🌟';  // Excellent
    if (score >= 70) return '✨';  // Good
    if (score >= 55) return '👍';  // Fair
    return '📊';                   // Below average
  }

  /**
   * Escape special characters for MarkdownV2
   * Characters: _ * [ ] ( ) ~ ` > # + - = | { } . !
   */
  escapeMarkdown(text: string): string {
    return text.replace(/[_*[\]()~`>#+=|{}.!\\-]/g, '\\$&');
  }

  /**
   * Format a compact message (for SMS-like brevity)
   */
  formatCompact(payload: AlertPayload): string {
    const topListing = payload.listings[0];
    if (!topListing) return '';

    return this.escapeMarkdown(
      `🎫 ${payload.eventName}\n` +
      `📍 ${payload.venueName}\n` +
      `💰 $${topListing.pricePerTicket} \\| Score: ${topListing.valueScore}\n`
    ) + `[Buy](${topListing.deepLink})`;
  }
}

/**
 * SMS Notifier
 * Sends alerts via Twilio SMS API
 */

import twilio from 'twilio';
import type { Twilio } from 'twilio';
import type { MessageInstance } from 'twilio/lib/rest/api/v2010/account/message';
import type {
  INotifier,
  AlertPayload,
  NotificationResult,
  NotificationChannel,
  DeliveryStatus,
} from '../base/notifier.interface.js';
import { SMSFormatter } from './sms.formatter.js';
import { logger, logAlertDelivery } from '../../utils/logger.js';
import { config } from '../../config/index.js';

// ============================================================================
// SMS Notifier Implementation
// ============================================================================

export class SMSNotifier implements INotifier {
  readonly channel: NotificationChannel = 'sms';

  private client: Twilio;
  private formatter: SMSFormatter;
  private fromNumber: string;
  private isInitialized: boolean = false;

  constructor() {
    this.client = twilio(config.twilio.accountSid, config.twilio.authToken);
    this.formatter = new SMSFormatter();
    this.fromNumber = config.twilio.phoneNumber;
  }

  // ==========================================================================
  // Initialization
  // ==========================================================================

  async initialize(): Promise<void> {
    if (this.isInitialized) return;

    if (!config.twilio.accountSid || !config.twilio.authToken) {
      throw new Error('Twilio credentials not configured');
    }

    if (!config.twilio.phoneNumber) {
      throw new Error('Twilio phone number not configured');
    }

    try {
      // Verify account by fetching account info
      const account = await this.client.api.accounts(config.twilio.accountSid).fetch();

      logger.info(`[SMS] Twilio initialized`, {
        accountName: account.friendlyName,
        fromNumber: this.fromNumber,
      });

      this.isInitialized = true;
    } catch (error) {
      throw new Error(`Failed to initialize Twilio: ${error}`);
    }
  }

  // ==========================================================================
  // Send Alert
  // ==========================================================================

  async sendAlert(payload: AlertPayload): Promise<NotificationResult> {
    const startTime = Date.now();

    try {
      await this.ensureInitialized();

      const message = this.formatter.formatAlert(payload);
      const segments = this.formatter.countSegments(message);

      logger.debug(`[SMS] Sending message`, {
        to: payload.userId,
        length: message.length,
        segments,
        estimatedCost: this.formatter.estimateCost(message),
      });

      const result: MessageInstance = await this.client.messages.create({
        body: message,
        from: this.fromNumber,
        to: payload.userId,
      });

      const latency = Date.now() - startTime;

      logAlertDelivery('sms', payload.userId, true, result.sid);

      logger.info(`[SMS] Alert sent successfully`, {
        to: payload.userId,
        sid: result.sid,
        status: result.status,
        latency,
        segments,
      });

      return {
        success: true,
        channel: 'sms',
        messageId: result.sid,
        timestamp: new Date(),
        deliveryStatus: this.mapTwilioStatus(result.status),
      };
    } catch (error) {
      const latency = Date.now() - startTime;
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';

      logAlertDelivery('sms', payload.userId, false, undefined, errorMessage);

      logger.error(`[SMS] Failed to send alert`, {
        to: payload.userId,
        error: errorMessage,
        latency,
      });

      // Handle specific Twilio errors
      const handled = this.handleTwilioError(error, payload.userId);

      return {
        success: false,
        channel: 'sms',
        error: handled.message,
        timestamp: new Date(),
        deliveryStatus: 'failed',
      };
    }
  }

  // ==========================================================================
  // Recipient Validation
  // ==========================================================================

  async validateRecipient(phoneNumber: string): Promise<boolean> {
    try {
      await this.ensureInitialized();

      // Use Twilio Lookup API to validate phone number
      const lookup = await this.client.lookups.v2
        .phoneNumbers(phoneNumber)
        .fetch();

      return lookup.valid;
    } catch (error) {
      logger.warn(`[SMS] Invalid phone number: ${phoneNumber}`, {
        error: error instanceof Error ? error.message : 'Unknown error',
      });
      return false;
    }
  }

  // ==========================================================================
  // Delivery Status
  // ==========================================================================

  async getDeliveryStatus(messageId: string): Promise<DeliveryStatus> {
    try {
      await this.ensureInitialized();

      const message = await this.client.messages(messageId).fetch();
      return this.mapTwilioStatus(message.status);
    } catch (error) {
      logger.error(`[SMS] Failed to get delivery status`, {
        messageId,
        error: error instanceof Error ? error.message : 'Unknown error',
      });
      return 'unknown';
    }
  }

  // ==========================================================================
  // Private Helpers
  // ==========================================================================

  private async ensureInitialized(): Promise<void> {
    if (!this.isInitialized) {
      await this.initialize();
    }
  }

  /**
   * Map Twilio message status to our DeliveryStatus
   */
  private mapTwilioStatus(status: string): DeliveryStatus {
    const statusMap: Record<string, DeliveryStatus> = {
      delivered: 'delivered',
      sent: 'pending',
      sending: 'pending',
      queued: 'pending',
      accepted: 'pending',
      receiving: 'pending',
      received: 'delivered',
      failed: 'failed',
      undelivered: 'failed',
      canceled: 'failed',
    };

    return statusMap[status] || 'unknown';
  }

  /**
   * Handle Twilio-specific errors
   */
  private handleTwilioError(
    error: unknown,
    phoneNumber: string
  ): { message: string; shouldDeactivate: boolean } {
    if (!(error instanceof Error)) {
      return { message: 'Unknown error', shouldDeactivate: false };
    }

    // Extract Twilio error code if available
    const twilioError = error as { code?: number; message: string };

    switch (twilioError.code) {
      case 21211: // Invalid phone number
        logger.warn(`[SMS] Invalid phone number: ${phoneNumber}`);
        return {
          message: 'Invalid phone number format',
          shouldDeactivate: true,
        };

      case 21612: // Unsubscribed
      case 21614: // Unsubscribed
        logger.warn(`[SMS] User unsubscribed: ${phoneNumber}`);
        return {
          message: 'User has unsubscribed from SMS',
          shouldDeactivate: true,
        };

      case 30003: // Unreachable
        logger.warn(`[SMS] Phone unreachable: ${phoneNumber}`);
        return {
          message: 'Phone number is unreachable',
          shouldDeactivate: false,
        };

      case 30004: // Blocked by carrier
        logger.warn(`[SMS] Blocked by carrier: ${phoneNumber}`);
        return {
          message: 'Message blocked by carrier',
          shouldDeactivate: false,
        };

      case 30005: // Unknown destination
        logger.warn(`[SMS] Unknown destination: ${phoneNumber}`);
        return {
          message: 'Unknown phone number',
          shouldDeactivate: true,
        };

      case 30006: // Landline
        logger.warn(`[SMS] Landline number: ${phoneNumber}`);
        return {
          message: 'Cannot send SMS to landline',
          shouldDeactivate: true,
        };

      case 20003: // Authentication error
        logger.error(`[SMS] Twilio authentication failed`);
        return {
          message: 'SMS service authentication error',
          shouldDeactivate: false,
        };

      default:
        return {
          message: twilioError.message,
          shouldDeactivate: false,
        };
    }
  }

  /**
   * Send a test SMS message
   */
  async sendTestMessage(phoneNumber: string, text: string): Promise<boolean> {
    try {
      await this.ensureInitialized();

      await this.client.messages.create({
        body: text,
        from: this.fromNumber,
        to: phoneNumber,
      });

      return true;
    } catch {
      return false;
    }
  }
}

/**
 * SMS Message Formatter
 * Formats alerts for SMS with character limits in mind
 */

import type { AlertPayload, TopValueListing } from '../base/notifier.interface.js';

// ============================================================================
// Constants
// ============================================================================

const MAX_SMS_LENGTH = 160;  // Single SMS segment
const MAX_TOTAL_LENGTH = 1600; // Maximum total for multi-segment SMS

// ============================================================================
// SMS Formatter
// ============================================================================

export class SMSFormatter {
  /**
   * Format a full alert message for SMS
   * Optimized for brevity while maintaining key info
   */
  formatAlert(payload: AlertPayload): string {
    const header = this.formatHeader(payload);
    const topListings = payload.listings.slice(0, 3); // Max 3 listings for SMS
    const listings = topListings.map((l, i) => this.formatListing(l, i + 1)).join('\n');
    const footer = this.formatFooter();

    const fullMessage = `${header}\n\n${listings}\n\n${footer}`;

    // Truncate if too long
    if (fullMessage.length > MAX_TOTAL_LENGTH) {
      return this.formatCompact(payload);
    }

    return fullMessage;
  }

  /**
   * Format compact header
   */
  private formatHeader(payload: AlertPayload): string {
    const date = this.formatShortDate(payload.eventDate);

    return (
      `🎫 ${this.truncate(payload.eventName, 40)}\n` +
      `📍 ${payload.venueName}\n` +
      `📅 ${date}`
    );
  }

  /**
   * Format a single listing (compact)
   */
  private formatListing(listing: TopValueListing, rank: number): string {
    return (
      `${rank}. Sec ${listing.section} Row ${listing.row}\n` +
      `   $${listing.pricePerTicket}/ea | Score: ${listing.valueScore}\n` +
      `   ${listing.deepLink}`
    );
  }

  /**
   * Format footer
   */
  private formatFooter(): string {
    return 'Reply STOP to unsubscribe';
  }

  /**
   * Format very compact message (single SMS if possible)
   */
  formatCompact(payload: AlertPayload): string {
    const topListing = payload.listings[0];
    if (!topListing) {
      return `🎫 ${payload.eventName} - No deals found`;
    }

    const date = this.formatShortDate(payload.eventDate);

    return (
      `🎫 ${this.truncate(payload.eventName, 30)}\n` +
      `${date} @ ${payload.venueName}\n\n` +
      `TOP: Sec ${topListing.section} $${topListing.pricePerTicket} (Score: ${topListing.valueScore})\n` +
      `${topListing.deepLink}\n\n` +
      `STOP to unsub`
    );
  }

  /**
   * Format just the essentials (minimal SMS)
   */
  formatMinimal(payload: AlertPayload): string {
    const topListing = payload.listings[0];
    if (!topListing) return '';

    return (
      `${this.truncate(payload.eventName, 25)} - ` +
      `$${topListing.pricePerTicket} Sec ${topListing.section} Score:${topListing.valueScore} ` +
      `${topListing.deepLink}`
    );
  }

  /**
   * Format date compactly
   */
  private formatShortDate(date: Date): string {
    return date.toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      hour: 'numeric',
      minute: '2-digit',
    });
  }

  /**
   * Truncate text with ellipsis
   */
  private truncate(text: string, maxLength: number): string {
    if (text.length <= maxLength) return text;
    return text.slice(0, maxLength - 3) + '...';
  }

  /**
   * Count SMS segments for a message
   */
  countSegments(message: string): number {
    // GSM-7 encoding: 160 chars per segment, or 153 for multi-segment
    // Unicode: 70 chars per segment, or 67 for multi-segment
    const hasUnicode = /[^\x00-\x7F]/.test(message);

    if (hasUnicode) {
      if (message.length <= 70) return 1;
      return Math.ceil(message.length / 67);
    } else {
      if (message.length <= 160) return 1;
      return Math.ceil(message.length / 153);
    }
  }

  /**
   * Estimate cost for sending this message
   * Based on Twilio rates (~$0.0075 per segment)
   */
  estimateCost(message: string, ratePerSegment: number = 0.0075): number {
    const segments = this.countSegments(message);
    return segments * ratePerSegment;
  }
}

/**
 * WhatsApp Notifier
 * Sends alerts via Twilio WhatsApp Business API
 */

import twilio from 'twilio';
import type { Twilio } from 'twilio';
import type { MessageInstance } from 'twilio/lib/rest/api/v2010/account/message';
import type {
  INotifier,
  AlertPayload,
  NotificationResult,
  NotificationChannel,
  DeliveryStatus,
} from '../base/notifier.interface.js';
import { WhatsAppFormatter } from './whatsapp.formatter.js';
import { logger, logAlertDelivery } from '../../utils/logger.js';
import { config } from '../../config/index.js';

// ============================================================================
// WhatsApp Notifier Implementation
// ============================================================================

export class WhatsAppNotifier implements INotifier {
  readonly channel: NotificationChannel = 'whatsapp';

  private client: Twilio;
  private formatter: WhatsAppFormatter;
  private fromNumber: string;
  private isInitialized: boolean = false;

  constructor() {
    this.client = twilio(config.twilio.accountSid, config.twilio.authToken);
    this.formatter = new WhatsAppFormatter();
    // WhatsApp numbers must be prefixed with 'whatsapp:'
    this.fromNumber = `whatsapp:${config.twilio.whatsappNumber || config.twilio.phoneNumber}`;
  }

  // ==========================================================================
  // Initialization
  // ==========================================================================

  async initialize(): Promise<void> {
    if (this.isInitialized) return;

    if (!config.twilio.accountSid || !config.twilio.authToken) {
      throw new Error('Twilio credentials not configured');
    }

    const whatsappNumber = config.twilio.whatsappNumber || config.twilio.phoneNumber;
    if (!whatsappNumber) {
      throw new Error('Twilio WhatsApp number not configured');
    }

    try {
      // Verify account
      const account = await this.client.api.accounts(config.twilio.accountSid).fetch();

      logger.info(`[WhatsApp] Twilio WhatsApp initialized`, {
        accountName: account.friendlyName,
        fromNumber: this.fromNumber,
      });

      this.isInitialized = true;
    } catch (error) {
      throw new Error(`Failed to initialize Twilio WhatsApp: ${error}`);
    }
  }

  // ==========================================================================
  // Send Alert
  // ==========================================================================

  async sendAlert(payload: AlertPayload): Promise<NotificationResult> {
    const startTime = Date.now();

    try {
      await this.ensureInitialized();

      const message = this.formatter.formatAlert(payload);

      // Format recipient with whatsapp: prefix
      const toNumber = this.formatWhatsAppNumber(payload.userId);

      logger.debug(`[WhatsApp] Sending message`, {
        to: toNumber,
        length: message.length,
      });

      const result: MessageInstance = await this.client.messages.create({
        body: message,
        from: this.fromNumber,
        to: toNumber,
      });

      const latency = Date.now() - startTime;

      logAlertDelivery('whatsapp', payload.userId, true, result.sid);

      logger.info(`[WhatsApp] Alert sent successfully`, {
        to: payload.userId,
        sid: result.sid,
        status: result.status,
        latency,
      });

      return {
        success: true,
        channel: 'whatsapp',
        messageId: result.sid,
        timestamp: new Date(),
        deliveryStatus: this.mapTwilioStatus(result.status),
      };
    } catch (error) {
      const latency = Date.now() - startTime;
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';

      logAlertDelivery('whatsapp', payload.userId, false, undefined, errorMessage);

      logger.error(`[WhatsApp] Failed to send alert`, {
        to: payload.userId,
        error: errorMessage,
        latency,
      });

      const handled = this.handleWhatsAppError(error, payload.userId);

      return {
        success: false,
        channel: 'whatsapp',
        error: handled.message,
        timestamp: new Date(),
        deliveryStatus: 'failed',
      };
    }
  }

  // ==========================================================================
  // Template Messages (for WhatsApp Business API)
  // ==========================================================================

  /**
   * Send a pre-approved template message
   * Required for initiating conversations with users who haven't messaged first
   */
  async sendTemplateMessage(
    userId: string,
    templateSid: string,
    parameters: Record<string, string>
  ): Promise<NotificationResult> {
    const startTime = Date.now();

    try {
      await this.ensureInitialized();

      const toNumber = this.formatWhatsAppNumber(userId);

      // Build content variables for template
      const contentVariables = JSON.stringify(parameters);

      const result = await this.client.messages.create({
        from: this.fromNumber,
        to: toNumber,
        contentSid: templateSid,
        contentVariables,
      });

      const latency = Date.now() - startTime;

      logger.info(`[WhatsApp] Template message sent`, {
        to: userId,
        sid: result.sid,
        templateSid,
        latency,
      });

      return {
        success: true,
        channel: 'whatsapp',
        messageId: result.sid,
        timestamp: new Date(),
        deliveryStatus: this.mapTwilioStatus(result.status),
      };
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';

      logger.error(`[WhatsApp] Failed to send template message`, {
        to: userId,
        error: errorMessage,
      });

      return {
        success: false,
        channel: 'whatsapp',
        error: errorMessage,
        timestamp: new Date(),
        deliveryStatus: 'failed',
      };
    }
  }

  // ==========================================================================
  // Recipient Validation
  // ==========================================================================

  async validateRecipient(phoneNumber: string): Promise<boolean> {
    try {
      await this.ensureInitialized();

      // Use Twilio Lookup API to validate phone number
      const lookup = await this.client.lookups.v2
        .phoneNumbers(phoneNumber)
        .fetch();

      // WhatsApp requires mobile numbers
      if (!lookup.valid) return false;

      // Could additionally check if WhatsApp is available on this number
      // using carrier info, but that requires additional API access

      return true;
    } catch (error) {
      logger.warn(`[WhatsApp] Invalid phone number: ${phoneNumber}`, {
        error: error instanceof Error ? error.message : 'Unknown error',
      });
      return false;
    }
  }

  // ==========================================================================
  // Delivery Status
  // ==========================================================================

  async getDeliveryStatus(messageId: string): Promise<DeliveryStatus> {
    try {
      await this.ensureInitialized();

      const message = await this.client.messages(messageId).fetch();
      return this.mapTwilioStatus(message.status);
    } catch (error) {
      logger.error(`[WhatsApp] Failed to get delivery status`, {
        messageId,
        error: error instanceof Error ? error.message : 'Unknown error',
      });
      return 'unknown';
    }
  }

  // ==========================================================================
  // Private Helpers
  // ==========================================================================

  private async ensureInitialized(): Promise<void> {
    if (!this.isInitialized) {
      await this.initialize();
    }
  }

  /**
   * Format phone number with whatsapp: prefix
   */
  private formatWhatsAppNumber(phoneNumber: string): string {
    // Remove any existing whatsapp: prefix
    const cleaned = phoneNumber.replace(/^whatsapp:/, '');

    // Ensure E.164 format (starts with +)
    const formatted = cleaned.startsWith('+') ? cleaned : `+${cleaned}`;

    return `whatsapp:${formatted}`;
  }

  /**
   * Map Twilio message status to our DeliveryStatus
   */
  private mapTwilioStatus(status: string): DeliveryStatus {
    const statusMap: Record<string, DeliveryStatus> = {
      delivered: 'delivered',
      read: 'delivered',
      sent: 'pending',
      sending: 'pending',
      queued: 'pending',
      accepted: 'pending',
      failed: 'failed',
      undelivered: 'failed',
      canceled: 'failed',
    };

    return statusMap[status] || 'unknown';
  }

  /**
   * Handle WhatsApp-specific errors
   */
  private handleWhatsAppError(
    error: unknown,
    phoneNumber: string
  ): { message: string; shouldDeactivate: boolean } {
    if (!(error instanceof Error)) {
      return { message: 'Unknown error', shouldDeactivate: false };
    }

    const twilioError = error as { code?: number; message: string };

    switch (twilioError.code) {
      case 21211: // Invalid phone number
        logger.warn(`[WhatsApp] Invalid phone number: ${phoneNumber}`);
        return {
          message: 'Invalid phone number format',
          shouldDeactivate: true,
        };

      case 21408: // Permission denied (user hasn't opted in)
        logger.warn(`[WhatsApp] User not opted in: ${phoneNumber}`);
        return {
          message: 'User has not opted in to receive WhatsApp messages',
          shouldDeactivate: false,
        };

      case 21610: // Unsubscribed
        logger.warn(`[WhatsApp] User unsubscribed: ${phoneNumber}`);
        return {
          message: 'User has unsubscribed from WhatsApp messages',
          shouldDeactivate: true,
        };

      case 63001: // Channel not found
        logger.error(`[WhatsApp] WhatsApp channel not configured`);
        return {
          message: 'WhatsApp channel not properly configured',
          shouldDeactivate: false,
        };

      case 63003: // Outside of message window
        logger.warn(`[WhatsApp] Outside 24-hour window: ${phoneNumber}`);
        return {
          message: 'Outside 24-hour messaging window - use template message',
          shouldDeactivate: false,
        };

      case 63007: // Template not found
        logger.error(`[WhatsApp] Message template not found`);
        return {
          message: 'WhatsApp message template not found',
          shouldDeactivate: false,
        };

      case 63016: // Message failed to send
        return {
          message: 'WhatsApp message failed to send',
          shouldDeactivate: false,
        };

      default:
        return {
          message: twilioError.message,
          shouldDeactivate: false,
        };
    }
  }

  /**
   * Send a test WhatsApp message
   */
  async sendTestMessage(phoneNumber: string, text: string): Promise<boolean> {
    try {
      await this.ensureInitialized();

      const toNumber = this.formatWhatsAppNumber(phoneNumber);

      await this.client.messages.create({
        body: text,
        from: this.fromNumber,
        to: toNumber,
      });

      return true;
    } catch {
      return false;
    }
  }
}
