    import { LRUCache } from 'lru-cache';

    private urlCache = new LRUCache<string, Buffer>({
      max: 30,             // max entries
      maxSize: 30_000_000, // 30MB total
      sizeCalculation: (value) => value.length,
      ttl: 1000 * 60 * 60, // 1 hour TTL
